def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal strips have rows whose zeros extend across the grid.
    if any(sum(v == 0 for v in row) > w // 2 for row in grid):
        out = [[7] * w for _ in range(h)]
        for r, row in enumerate(grid):
            if 0 in row:
                out[r][-3:] = row[:3]
            else:
                out[r][:3] = row[:3]
        return out
    # Vertical strips: copy the marked three-row edge to the other edge.
    top = any(9 in row for row in grid[:3])
    source = grid[:3] if top else grid[-3:]
    out = [[7] * w for _ in range(h)]
    start = h - 3 if top else 0
    out[start:start+3] = [row[:] for row in source]
    # Markers between two zeros travel; endpoint markers remain behind.
    source_start = 0 if top else h - 3
    for i, row in enumerate(source):
        for c, value in enumerate(row):
            if value == 9:
                left_zero = c > 0 and row[c-1] == 0
                right_zero = c + 1 < w and row[c+1] == 0
                if not (left_zero and right_zero):
                    out[source_start+i][c] = 9
    return out

